        if char == "(":
            current_part = "("
        elif char == ")":
            current_part += ")"
            extracted_parts.append(current_part)  # Add the balanced part to the list of extracted parts
            current_part = ""  # Reset the current part
        else:
            current_part += char

    return extracted_parts

