from typing import List

def separate_paren_groups(paren_string: str) -> List[str]:
    paren_string = paren_string.replace(" ", "")  # Remove spaces from the input string
    extracted_parts = []  # Initialize an empty list to store the extracted parts
    current_part = ""  # Initialize an empty string to store the current part

    stack = []
    start = 0

    for i, char in enumerate(paren_string):
        if char == "(":
            stack.append(i)
        elif char == ")":
            if stack:
                start = stack.pop()
                extracted_parts.append(paren_string[start:i+1])

    return extracted_parts
